import React, { createContext, useContext, useEffect, useState } from 'react';
import {
  getMyFavorites,
  addToFavorites,
  removeFromFavorites
} from '../services/favoriteService';

const FavoritesContext = createContext(null);

export const FavoritesProvider = ({ children }) => {
  const [favoriteIds, setFavoriteIds] = useState(new Set());
  const [loading, setLoading] = useState(true);

  // 🔹 Загружаем избранное при старте
  useEffect(() => {
    loadFavorites();
  }, []);

  const loadFavorites = async () => {
    try {
      const data = await getMyFavorites();
      const ids = new Set(data.map(f => f.tour.id));
      setFavoriteIds(ids);
    } catch (e) {
      console.error('Ошибка загрузки избранного', e);
    } finally {
      setLoading(false);
    }
  };

  const toggleFavorite = async (tourId) => {
    try {
      if (favoriteIds.has(tourId)) {
        await removeFromFavorites(tourId);
        setFavoriteIds(prev => {
          const s = new Set(prev);
          s.delete(tourId);
          return s;
        });
      } else {
        await addToFavorites(tourId);
        setFavoriteIds(prev => new Set(prev).add(tourId));
      }
    } catch (e) {
      console.error('Ошибка изменения избранного', e);
    }
  };

  const isFavorite = (tourId) => favoriteIds.has(tourId);

  return (
    <FavoritesContext.Provider
      value={{
        favoriteIds,
        isFavorite,
        toggleFavorite,
        loading
      }}
    >
      {children}
    </FavoritesContext.Provider>
  );
};

export const useFavorites = () => {
  const ctx = useContext(FavoritesContext);
  if (!ctx) {
    throw new Error('useFavorites must be used inside FavoritesProvider');
  }
  return ctx;
};
